const styles=new CSSStyleSheet;styles.replaceSync('/*\n * Copyright 2021 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n.css-length {\n  display: inline-block;\n  position: relative;\n  outline: none;\n}\n\n.css-length.overloaded {\n  text-decoration: line-through;\n}\n\n.value {\n  cursor: ew-resize;\n}\n\n.unit-dropdown {\n  display: none;\n}\n\n.unit-dropdown select {\n  all: unset;\n  cursor: pointer;\n  opacity: 0%;\n  width: 0.8em;\n  background-color: var(--color-background);\n}\n\n.icon {\n  position: absolute;\n  display: inline-block;\n  -webkit-mask-image: var(--image-file-chevron-down);\n  -webkit-mask-repeat: no-repeat;\n  background-color: var(--icon-default);\n  transform: scale(0.7);\n  margin-left: -7px;\n  margin-top: -3px;\n  content: "";\n  height: 2em;\n  width: 2em;\n}\n\n:host(:not(:last-child)) {\n  margin-right: 0.1em;\n}\n\n:host(:not(:last-child)) .unit-dropdown {\n  position: absolute;\n}\n\n.css-length:hover .unit-dropdown {\n  display: inline-block;\n}\n\n:host(:last-child) .unit-dropdown select {\n  width: 0.6em;\n}\n\n/*# sourceURL=cssLength.css */\n');export default styles;